contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address other, address _owner) public payable {
        // Setup: try to transfer ownership to `other` from the test contract (the deployer and initial owner).
        // This call succeeds in the fresh deployment, setting c.owner() = other.
        c.setOwner(other);

        // Read the current owner after setup.
        address prevOwner = c.owner();

        // Deciding call: the test contract (msg.sender) attempts to set owner to _owner.
        bool reverted;
        try c.setOwner(_owner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call reverts exactly when the caller is not the current owner at call time.
        // Since msg.sender here is this test contract, this is equivalent to msg.sender != prevOwner.
        assert(reverted == (msg.sender != prevOwner));
    }

    receive() external payable {}
}

